"""Slack layouts for the v2 signup card, its three thread replies, and its modals."""
import json
from typing import Any

from src.shapes import Block
from src.signup import teams
from src.slack.alerts import _browser, clerk_lines, maxmind_line, photo, when
from src.slack.client import escape
from src.slack.run import _clip

SEP = "  ·  "
MAX_CANDIDATES = 5
# every v2 interactive id starts with this so the live handler can forward it
PREFIX = "v2_"


def _join(*parts: str, sep: str = SEP) -> str: return sep.join(p for p in parts if p)
def _link(url: str, label: str) -> str: return f"<{url}|{escape(label)}>" if url else escape(label)
def _ctx(*parts: str) -> Block: return {"type": "context", "elements": [{"type": "mrkdwn", "text": _clip(_join(*parts), 3000)}]}
def _section(text: str, accessory: dict[str, Any] | None = None) -> Block:
    block: Block = {"type": "section", "text": {"type": "mrkdwn", "text": _clip(text, 3000)}}
    if accessory:
        block["accessory"] = accessory
    return block
def _button(text: str, action_id: str, value: str = "", *, style: str = "", url: str = "") -> dict[str, Any]:
    button = {"type": "button", "text": {"type": "plain_text", "text": text}, "action_id": PREFIX + action_id}
    button |= {k: v for k, v in (("value", value), ("style", style), ("url", url)) if v}
    return button
def _pictured(text: str, url: str, alt: str) -> Block:
    """A context line led by a small inline avatar; section accessories render too large for a feed."""
    elements: list[dict[str, Any]] = [{"type": "image", "image_url": photo(url), "alt_text": alt or "photo"}] if url else []
    return {"type": "context", "elements": [*elements, {"type": "mrkdwn", "text": _clip(text, 3000)}]}


def role(person: dict[str, Any] | None) -> str:
    person = person or {}
    title, company = str(person.get("title") or ""), str(person.get("company") or "")
    if title and company:
        return f"{title} at {company}"
    return _clip(str(person.get("headline") or title or company), 90)


def pct(confidence: Any) -> str:
    try:
        return f"{round(float(confidence) * 100)}%"
    except (TypeError, ValueError):
        return ""


def text(profile: dict[str, Any]) -> str:
    return _join("signup", str(profile.get("email") or "no email"), str(profile.get("name") or ""), sep=" · ")


def _facts(profile: dict[str, Any], team: dict[str, Any] | None) -> list[str]:
    return [teams.label(team), str(profile.get("place") or ""), str(profile.get("browser") or ""),
            f"via {profile['method']}" if profile.get("method") else ""]


def card(profile: dict[str, Any], state: dict[str, Any]) -> list[Block]:
    """state: team, confirmed (person), top (person), lookup ("pending" | "failed" | "done"), confirmed_by."""
    email = str(profile.get("email") or "")
    mail = _link(f"mailto:{email}", email) if email else "no email"
    team = state.get("team")
    confirmed = state.get("confirmed")
    if confirmed and confirmed.get("kind") == "company":
        return _company_card(profile, state, confirmed, mail)
    if confirmed:
        name = str(confirmed.get("name") or profile.get("name") or email)
        blocks = [
            _section(_join(f"*{escape(name)}*", escape(role(confirmed)), sep="  —  ")),
            _ctx(mail, _link(confirmed["url"], f"in/{confirmed['slug']}"), *_facts(profile, team)),
        ]
        if by := state.get("confirmed_by"):
            blocks.append(_ctx(f"LinkedIn confirmed by <@{by}>"))
        return blocks
    name = str(profile.get("name") or email or "unknown")
    head = _pictured(_join(f"*{escape(name)}*", mail if email != name else ""), str(profile.get("image") or ""), name)
    blocks = [head, _ctx(*_facts(profile, team))]
    lookup, top = state.get("lookup"), state.get("top")
    if lookup == "pending":
        blocks.append(_ctx("Looking up identity…"))
    elif lookup == "failed":
        blocks.append(_ctx("Identity lookup failed — retry from the thread"))
    elif top:
        blocks.append(_ctx(f"Possible LinkedIn: {_link(top['url'], f'in/{top['slug']}')}",
                           escape(role(top)), _join(pct(top.get("confidence")), "unconfirmed", sep=" ")))
    else:
        blocks.append(_ctx("No LinkedIn match"))
    return blocks


def _company_card(profile: dict[str, Any], state: dict[str, Any], company: dict[str, Any], mail: str) -> list[Block]:
    """No individual to find: the card closes on the company page, led by its logo."""
    name = str(company.get("name") or company["slug"])
    size = f"{company['headcount']} employee" + ("s" if company["headcount"] != 1 else "") if company.get("headcount") else ""
    blocks = [
        _pictured(_join(f"*{escape(name)}*", "company account", sep="  —  "), str(company.get("photo") or ""), name),
        _ctx(mail, _link(company["url"], f"company/{company['slug']}"), escape(str(company.get("industry") or "")), size,
             *_facts(profile, state.get("team"))),
    ]
    if by := state.get("confirmed_by"):
        blocks.append(_ctx(f"Company confirmed by <@{by}>"))
    return blocks


def actions(user_id: str, *, crm_url: str = "", confirmed: bool = False) -> tuple[str, list[Block]]:
    buttons = [_button("See all details", "details", user_id)]
    if crm_url:
        buttons.append(_button("Open in CRM", "crm", user_id, url=crm_url))
    if confirmed:
        buttons.append(_button("Change LinkedIn", "change", user_id))
    return "Signup actions", [{"type": "actions", "elements": buttons}]


def _candidate(user_id: str, person: dict[str, Any], index: int) -> list[Block]:
    name = str(person.get("name") or person["slug"])
    detail = _join(escape(role(person)), escape(str(person.get("location") or "")))
    source = "identity match" if person.get("source") == "identity" else "same name in taiga"
    meta = _join(_link(person["url"], f"in/{person['slug']}"), pct(person.get("confidence")), source)
    return [_pictured(_join(_join(f"*{escape(name)}*", detail), meta, sep="\n"), str(person.get("photo") or ""), name),
            {"type": "actions", "elements": [_button("This is them", f"pick_{index}", f"{user_id}|{person['slug']}", style="primary")]}]


def linkedin(user_id: str, state: dict[str, Any]) -> tuple[str, list[Block]]:
    confirmed = state.get("confirmed")
    if confirmed:
        who = f" by <@{state['confirmed_by']}>" if state.get("confirmed_by") else ""
        at = when(str(state.get("confirmed_at") or ""))
        if confirmed.get("kind") == "company":
            page = _link(confirmed["url"], f"company/{confirmed['slug']}")
