                <span style={{ width: 9, height: 9, background: C.orange, borderRadius: 2, display: "inline-block" }} />
                {st.s.eyebrow}
              </div>
              <div style={{ fontFamily: SANS, fontWeight: 360 as never, fontSize: st.s.bigSize ?? 84, letterSpacing: "-0.03em",
