              <div style={{ fontFamily: SANS, fontSize: 24, color: "rgba(33,19,14,0.62)", marginTop: 14, lineHeight: 1.3 }}>{st.s.sub}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

// ---------- lower third ----------
export const LowerThird: React.FC<{ dur: number }> = ({ dur }) => {
  const f = useCurrentFrame();
