p.write_text(s)
p=Path("src/timeline.ts"); s=p.read_text()
s=s.replace('export const RATE = edl.rate ?? 1;','export const RATE = edl.rate ?? 1;\n/** "footage" = graded only, "footage-dof" = graded + AI background blur */\nexport const FOOTAGE: string = (edl as { footage?: string }).footage ?? "footage";')
p.write_text(s)
EOF
