        <div style={{ fontFamily: SANS, fontWeight: 360 as never, fontSize: 92, letterSpacing: "-0.035em", color: C.ink, marginTop: 18,
          opacity: e(12), transform: `translateY(${(1 - e(12)) * 14}px)` }}>
