      <Shot seg={B} keys={[{ at: B.start, f: "side" }, { at: tabsOut, f: "sideClose" }]} />
      <Shot seg={Cs} keys={[{ at: Cs.start, f: "close" }]} />
      <Shot seg={D} keys={[{ at: D.start, f: "side" }, { at: turned, f: "sideClose" }]} />
