          <div style={{ fontFamily: SANS, fontSize: 52, color: "rgba(33,19,14,0.7)", marginTop: 18, letterSpacing: "-0.02em" }}>
            <Decode text="Maria Reyes · Larkspur" start={cto + 6} dur={14} />
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
